import{_ as e,c as t,o,a2 as i}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"Redirects","description":"","frontmatter":{"sidebarPos":7,"sidebarTitle":"Redirects","sidebarGroupTitle":"Cms","outline":"deep"},"headers":[],"relativePath":"guide/cms/redirects.md","filePath":"guide/cms/redirects.md","lastUpdated":1784841066000}'),r={name:"guide/cms/redirects.md"},c=i('<h1 id="redirects" tabindex="-1">Redirects <a class="header-anchor" href="#redirects" aria-label="Permalink to &quot;Redirects&quot;">​</a></h1><p>Visitor redirects are CMS rules evaluated on the public front stack before (or instead of) resolving a page.</p><h2 id="entity" tabindex="-1">Entity <a class="header-anchor" href="#entity" aria-label="Permalink to &quot;Entity&quot;">​</a></h2><p><strong>Redirect</strong>: <code>from_path</code>, <code>to_path</code>, <code>locale</code>, <code>status_code</code>, <code>is_active</code>.</p><p>On save/delete, <code>RedirectRepository</code> syncs a UrlRoute with <code>kind = redirect_source</code> for the from-path (<code>CmsUrlRouteRegistry</code>).</p><h2 id="runtime" tabindex="-1">Runtime <a class="header-anchor" href="#runtime" aria-label="Permalink to &quot;Runtime&quot;">​</a></h2><ol><li>Front middleware <code>modules.cms.visitor.redirect</code> (<code>VisitorRedirectMiddleware</code>) when <code>cms_routing.visitor_redirects_enabled</code></li><li><code>CmsVisitorRedirectResolver</code>: <ul><li>Skips admin/api/system and <a href="./public-routing">reserved system prefixes</a></li><li>If an active <strong><code>page_public</code></strong> UrlRoute exists for the path → <strong>no redirect</strong> (page wins)</li><li>Else match <code>redirect_source</code> UrlRoute → active Redirect, or fall back to scanning Redirect rows</li></ul></li><li>Issues HTTP redirect (clamped 3xx; absolute or site-relative <code>to_path</code>)</li></ol><h2 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to &quot;Config&quot;">​</a></h2><ul><li><code>modularous.cms_routing.visitor_redirects_enabled</code></li><li><code>modularous.cms_routing.visitor_redirect_exclude_prefixes</code> (e.g. <code>api</code>, <code>sanctum</code>, <code>livewire</code>) — separate from catch-all excludes</li></ul><p>See <a href="./configuration">Configuration</a>.</p>',10),a=[c];function d(s,l,n,u,_,p){return o(),t("div",null,a)}const f=e(r,[["render",d]]);export{m as __pageData,f as default};
